# ============================================================
# İK Odası — Yönetici notu + AI içgörü tepki katmanı — DEPLOY
# ÖN KOŞUL: ik_notu_ddl.sql psql'de çalışmış olmalı (2 tablo).
# Build dizininde (/opt/krb-assessment) yapıştır-çalıştır.
# ============================================================

# 1) Patch'i sunucuda oluştur (scp yok)
echo "" | base64 -d > patch_ik_notu.py

# 2) Uygula (idempotent; .notbak yedekleri; marker'lı)
python3 patch_ik_notu.py .

# 3) Kaynak doğrula (server 2 marker + 2 uç; client 2 marker)
grep -c "IK_ODA_ORG_V4\|IK_NOTU_EP_V1" server_container.mjs
grep -c "/api/bi/ik/not\|/api/bi/ik/tepki" server_container.mjs
grep -c "IK_NOTU_JS_V1\|IK_NOTU_CSS_V1" shells/ik.html

# 4) İmajı kur + konteyneri tazele
docker build -t krb-assessment:secure . && docker compose up -d --force-recreate krb-assessment

# 5) Konteyner içi doğrula
docker exec krb-assessment grep -c "IK_ODA_ORG_V4" /app/server.mjs
docker exec krb-assessment sh -c "grep -rc IK_NOTU_JS_V1 /app --include=ik.html 2>/dev/null || true"

# 6) Disk
docker image prune -f
